with lines as (select id, customer_id, created_at, explode_outer(coupon_codes) as value from carts), enriched as (select a.*, b.signup_date, b.email, b.segment from lines a left join customers b on a.customer_id = b.id), with_dims as (select e.id, e.customer_id, e.created_at, e.value, e.signup_date, e.email, e.segment, p.name, p.age, p.signup_date as customer_signup_date from enriched e left join customers p on e.customer_id = p.id where p.city in ('Bangkok', 'London')), enriched_carts as (select s.id, s.customer_id, s.created_at, s.name, s.age, b.city, b.age as customer_age, b.segment as customer_segment from with_dims s left join customers b on s.customer_id <=> b.id), valid as (select id, customer_id, created_at, name, age, city, customer_age, customer_segment, round(age, 2) age_rounded from enriched_carts where created_at >= to_date('2025-03-02') and city not in ('Bangkok', 'Chiang Mai', 'London')), scored as (select customer_id, city, customer_segment, age_rounded, min(customer_age) over (partition by city) city_min_customer_age, max(age_rounded) over (order by cast(created_at as bigint) asc range between 900 preceding and current row) age_rounded_max_15m from valid) select dim.segment, dim.city as customer_city, count(*) as cnt, sum(e.age_rounded) as total_age_rounded, max(e.age_rounded_max_15m) as max_age_rounded_max_15m from scored e inner join customers dim on e.customer_id = dim.id group by grouping sets ((dim.segment, dim.city), (dim.segment), ())
